entries[106108] = { ["name"] = "Heldenhafte Willensstärke", ["text"] = "Sofort 5 sek. Abklingzeit\nStählt die Konzentration des Zaubernden, um den Mächten des Zwielichts zu widerstehen. Transportiert den Zaubernden bis zu 5 Sek. lang aus dem Zwielichtreich hinaus, jedoch kann er weder angreifen noch Zauber wirken oder sich bewegen, während er sich konzentriert." }
entries[106174] = { ["name"] = "Stunde des Zwielichts", ["text"] = "Unbegrenzte Reichweite\nWirken in 0.25 sek.\nDie Stunde des Zwielichts bricht über Ultraxions Gegner herein. Gegner, die sich im Zwielichtreich befinden, erleiden 300000 Schattenschaden, dem nicht widerstanden werden kann. Gegner in der normalen Welt werden sofort zurück ins Zwielichtreich gezogen. Wenn keine Gegner von 'Stunde des Zwielichts' getroffen werden, erleiden die Aspekte den Gesamtschaden des Angriffs und der Schild, der die Drachenseele schützt, wird gestört, womit das Ende allen Lebens auf Azeroth eingeleitet wird." }
